; Paragon 50 - Heraeus Surgical / LaserSonics - firmware 68000 (ROM HI/LO)
; Desmontagem comentada gerada a partir de Paragon_50_HI.BIN e Paragon_50_LO.BIN
;
; Layout recuperado da imagem:
;   - HI = bytes pares (D15-D8), LO = bytes impares (D7-D0), cada EPROM 32 KB -> 64 KB.
;   - Os 4 blocos de 16 KB do arquivo intercalado (HI/LO) estao em ordem INVERTIDA:
;       arquivo $C000-$FFFF = ROM $F80000-$F83FFF   arquivo $8000-$BFFF = ROM $F84000-$F87FFF
;       arquivo $4000-$7FFF = ROM $F88000-$F8BFFF   arquivo $0000-$3FFF = ROM $F8C000-$F8FFFF
;     isto e: endereco_ROM = $F80000 + (offset_arquivo XOR $C000)  (linhas A15/A14 invertidas na leitura).
;   - ROM mapeada em $F80000-$F8FFFF. RAM/NVRAM (2x DS1230Y) em $000000-$00FFFF.
;   - Vetor de reset = $F84000; SSP = $1F00; vetores copiados da ROM para RAM $0 no boot.
;
; ATENCAO: listagem de referencia (sintaxe Motorola). Nao foi verificado o reassemblamento bit-a-bit;
; os 4 hex words de cada instrucao ficam no comentario para conferencia contra a ROM.

;==============================================================================
; EQUATES DE I/O (inferidos do codigo)
;==============================================================================
IN_WORD_0          equ $020000      ; entrada 16 bits (a identificar: chaves/estado)
DAC_A              equ $02000a      ; DAC 12 bits canal A (escala 0..5000)
DAC_B              equ $02000c      ; DAC 12 bits canal B (escala 0..125000)
T8254_CTRL         equ $020010      ; 8254 palavra de controle
T8254_CNT2         equ $020012      ; 8254 contador 2
T8254_CNT1         equ $020014      ; 8254 contador 1
T8254_CNT0         equ $020016      ; 8254 contador 0
OUT_LATCH_HI       equ $020018      ; latch de saidas 16 bits (palavra alta de saidas)
OUT_LATCH_LO       equ $020020      ; latch de saidas 16 bits (palavra baixa de saidas)
IN_PORT_B          equ $020028      ; entrada 16 bits B (lida e invertida com EOR $FF34)
IN_PORT_A          equ $020030      ; entrada 16 bits A (lida e invertida com EOR $1BD3)
OUT_BYTE_A         equ $040180      ; saida 8 bits A (latch)
OUT_BYTE_B         equ $04018a      ; saida 8 bits B (latch)
IN_BYTE_A          equ $040194      ; entrada 8 bits (A/D ou chaves)
IN_BYTE_B          equ $04019c      ; entrada 8 bits (A/D ou chaves)
DUART_MR1A_MR2A    equ $fa0000      ; 68681 canal A: MR1/MR2 (modo)
DUART_SRA_CSRA     equ $fa0002      ; 68681 SRA (leitura) / CSRA clock select (escrita)
DUART_SRA          equ $fa0003      ; 68681 SRA status canal A (b2=TxRDY b0=RxRDY)
DUART_CRA          equ $fa0004      ; 68681 CRA comando canal A
DUART_THRA         equ $fa0006      ; 68681 THRA/RHRA dado canal A
DUART_ACR_IPCR     equ $fa0008      ; 68681 IPCR (leit.) / ACR (escr.)
DUART_ISR_IMR      equ $fa000a      ; 68681 ISR (leit.) / IMR (escr.)
DUART_ISR          equ $fa000b      ; 68681 ISR byte
DUART_CTUR         equ $fa000c      ; 68681 contador/timer: byte alto
DUART_CTLR         equ $fa000e      ; 68681 contador/timer: byte baixo
DUART_MR1B_MR2B    equ $fa0010      ; 68681 canal B: MR1/MR2
DUART_SRB_CSRB     equ $fa0012      ; 68681 SRB / CSRB
DUART_SRB          equ $fa0013      ; 68681 SRB status canal B (b2=TxRDY b0=RxRDY)
DUART_CRB          equ $fa0014      ; 68681 CRB comando canal B
DUART_THRB         equ $fa0016      ; 68681 THRB/RHRB dado canal B
DUART_IVR          equ $fa0018      ; 68681 IVR vetor de interrupcao (=$1F)
DUART_IP_OPCR      equ $fa001a      ; 68681 portas: IP (leit.) / OPCR (escr.)
DUART_IP           equ $fa001b      ; 68681 porta de entrada IP0-IP6
DUART_SOPR         equ $fa001c      ; 68681 SET output bits (leit.=start counter)
DUART_ROPR         equ $fa001e      ; 68681 RESET output bits (leit.=stop counter / limpa IRQ timer)

;==============================================================================
; VARIAVEIS EM RAM (inferidas do codigo)
;==============================================================================
STACK_TOP          equ $001f00      ; topo da pilha (SSP inicial)
MODE_TABLE         equ $002000      ; tabela de parametros por modo: 6 x $244 bytes (NVRAM)
power_set_mW       equ $002dac      ; potencia ajustada em mW (limite 500..50000)
dac_b_req          equ $002dbc      ; pedido DAC B (max 125000)
cur_state          equ $002df6      ; estado atual da maquina de estados (0..3)
prev_state         equ $002dfa      ; estado anterior
in_a_raw           equ $002fb0      ; leitura bruta IN_PORT_A
in_b_raw           equ $002fb2      ; leitura bruta IN_PORT_B
txq_buf            equ $003118      ; fila de transmissao serial: 150 entradas x 8 bytes (ptr, ptr_flag)
tick_count         equ $00436a      ; contador de tempo do sistema (+20 por tick)
dac_a_req          equ $0043c6      ; pedido DAC A (10..5000)
latch_b_img        equ $0043de      ; imagem do latch OUT_BYTE_B
substate           equ $00447a      ; sub-estado dentro do estado (0..7)
event              equ $0044be      ; evento atual p/ tabela de transicao
fault_flags        equ $0045a2      ; flags de falha
out_img            equ $0045aa      ; imagem das saidas
latch_a_img        equ $0045c0      ; imagem do latch OUT_BYTE_A
adc_in0            equ $0045c2      ; amostra IN_BYTE_B (8 bits)
adc_in1            equ $0045c4      ; amostra IN_BYTE_A (8 bits)
rx_buf_ptr         equ $004614      ; ptr de recepcao (ISR)
err_msg_tbl        equ $004626      ; tabela de ponteiros das mensagens de erro de sistema
state_trans_tbl    equ $0047a6      ; tabela de transicao: [evento*16 + estado*4]
state_handler_tbl  equ $0047f6      ; tabela de enderecos dos handlers de estado
cur_mode           equ $004928      ; modo laser atual (0=CW,1=COAG1,2=COAG2,3=BLEND3,4=CUT4,5=CUT5)
isr_busy           equ $004980      ; flag de reentrancia da ISR
dac_a_cur          equ $004988      ; valor atual DAC A
dac_b_cur          equ $00498c      ; valor atual DAC B
txq_tail           equ $004b9e      ; indice de insercao da fila TX
txq_head           equ $004ba2      ; indice de retirada da fila TX

        org $f80000

