; txq_pump_a  (f8c47c)
; Bombeia a fila TX para o canal A: se TxRDY, envia proximo byte da string na fila (150 entradas).
; tamanho ~130 bytes; chamada por 1 ponto(s)
; I/O: DUART_SRA, DUART_THRA
;------------------------------------------------------------------------------
txq_pump_a:
        movem.l a2-a3,-(a7)                       ; f8c47c: 48e7 0030             
        movea.l #$00004ba2,a2                     ; f8c480: 247c 0000 4ba2        
        movea.l #$00003118,a3                     ; f8c486: 267c 0000 3118        
        movea.l (a2),a1                           ; f8c48c: 2252                  
        cmpa.l  txq_tail,a1                       ; f8c48e: b3f9 0000 4b9e         ; indice de insercao da fila TX
        beq.s   L_c4f8                            ; f8c494: 6762                  
        move.b  DUART_SRA,d0                      ; f8c496: 1039 00fa 0003         ; 68681 SRA status canal A (b2=TxRDY b0=RxRDY)
        btst    #2,d0                             ; f8c49c: 0800 0002             
        beq.s   L_c4f8                            ; f8c4a0: 6756                  
